INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('The quick brown fox jumps over the lazy dog.', 'Der schnelle braune Fuchs springt ueber den faulen Hund.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Never gonna give you up, never gonna let you down.', 'Ich werde dich niemals aufgeben, dich niemals im Stich lassen.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('To be, or not to be, that is the question.', 'Sein oder Nichtsein, das ist hier die Frage.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('I have a dream that one day this nation will rise up.', 'Ich habe einen Traum, dass sich diese Nation eines Tages erheben wird.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('The only thing we have to fear is fear itself.', 'Das Einzige, wovor wir Angst haben muessen, ist die Angst selbst.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('The early bird catches the worm.', 'Der fruehe Vogel faengt den Wurm.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Better late than never.', 'Besser spaet als nie.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Actions speak louder than words.', 'Taten sagen mehr als Worte.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('All roads lead to Rome.', 'Alle Wege fuehren nach Rom.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Practice makes perfect.', 'Uebung macht den Meister.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Knowledge is power.', 'Wissen ist Macht.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Time is money.', 'Zeit ist Geld.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('The apple does not fall far from the tree.', 'Der Apfel faellt nicht weit vom Stamm.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Where there is a will, there is a way.', 'Wo ein Wille ist, ist auch ein Weg.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Out of sight, out of mind.', 'Aus den Augen, aus dem Sinn.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Silence is golden.', 'Schweigen ist Gold.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('I think, therefore I am.', 'Ich denke, also bin ich.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('The end justifies the means.', 'Der Zweck heiligt die Mittel.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Rome was not built in a day.', 'Rom wurde nicht an einem Tag erbaut.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Opposites attract.', 'Gegensaetze ziehen sich an.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('What are you doing this weekend?', 'Was machst du dieses Wochenende?');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('I would like a cup of coffee please.', 'Ich moechte bitte eine Tasse Kaffee.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Excuse me, where is the train station?', 'Entschuldigung, wo ist der Bahnhof?');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('I do not speak German very well.', 'Ich spreche nicht sehr gut Deutsch.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Can you help me please?', 'Koennen Sie mir bitte helfen?');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('The weather is beautiful today.', 'Das Wetter ist heute schoen.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('How much does this cost?', 'Wie viel kostet das?');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('I am looking for a supermarket.', 'Ich suche einen Supermarkt.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Have a nice day.', 'Einen schoenen Tag noch.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Life is like a box of chocolates.', 'Das Leben ist wie eine Schachtel Pralinen.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('May the Force be with you.', 'Moege die Macht mit dir sein.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('Houston, we have a problem.', 'Houston, wir haben ein Problem.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('I will be back.', 'Ich komme wieder.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('We learn from our mistakes.', 'Wir lernen aus unseren Fehlern.');
INSERT INTO phrase_entity (phrase_en, phrase_de) VALUES ('This is the beginning of a beautiful friendship.', 'Das ist der Beginn einer wunderbaren Freundschaft.');